import csv
import io

text = 'region,units,price\nNorth,10,2.5\n"South, East",4,10.0\nNorth,2,2.5\n"South, East",1,10.0\nWest,3,3.0\n'
totals = {}
for row in csv.DictReader(io.StringIO(text)):
    revenue = int(row["units"]) * float(row["price"])
    totals[row["region"]] = totals.get(row["region"], 0) + revenue
for region in sorted(totals):
    print(f"{region}: {totals[region]:.2f}")
